-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Personajes de High School DxD: OPI: 22. Cada fila lleva todo: datos, icono, biografia y
-- materiales de ascension.
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.

insert into public.characters (
  id, game_id, name, image_url, rarity, element, level_cap, description, role, path, signature, is_upcoming, biography, biography_source, biography_en, biography_source_en, biography_es, biography_source_es, biography_es_translated, ascension
)
